var DIAGRAMS={};
DIAGRAMS.topology={title:'PCIe topology',cap:'Root Complex at the top, an endpoint on one Root Port, a switch with three endpoints on the other. Routing is simple because every device has exactly one path to the root.',svg:`<svg viewBox="0 0 760 400" role="img" aria-label="PCIe tree topology"><title>PCIe tree topology</title><rect class="box" x="280" y="8" width="200" height="36" rx="6" /><text class="h" x="380" y="31" text-anchor="middle">CPU + Memory</text><line class="ln" x1="380" y1="44" x2="380" y2="66"/><rect class="tl" x="230" y="66" width="300" height="74" rx="6" /><text class="h" x="380" y="86" text-anchor="middle">Root Complex (RC)</text><rect class="box" x="250" y="104" width="110" height="28" rx="6" /><text class="s" x="305" y="122" text-anchor="middle">Root Port A</text><rect class="box" x="400" y="104" width="110" height="28" rx="6" /><text class="s" x="455" y="122" text-anchor="middle">Root Port B</text><polyline class="lna" points="305,132 305,190 130,190 130.0,240.0"/><polygon class="ah" points="130.0,248.0 125.5,239.0 134.5,239.0"/><text class="s d" x="218" y="183" text-anchor="middle">x4 · Gen4</text><rect class="dl" x="60" y="250" width="140" height="52" rx="6" /><text class="h" x="130" y="273" text-anchor="middle">Endpoint</text><text class="s d" x="130" y="290" text-anchor="middle">NVMe SSD</text><line class="lna" x1="455" y1="132" x2="455" y2="190"/><text class="s d" x="470" y="165" text-anchor="start">x8</text><rect class="pl" x="380" y="190" width="150" height="52" rx="6" /><text class="h" x="455" y="212" text-anchor="middle">Switch</text><text class="xs d" x="455" y="229" text-anchor="middle">upstream port on top</text><line class="ln" x1="455" y1="242" x2="455" y2="272"/><line class="ln" x1="390" y1="272" x2="670" y2="272"/><line class="ln" x1="390" y1="272" x2="390" y2="320"/><rect class="dl" x="330" y="320" width="120" height="52" rx="6" /><text class="h" x="390" y="343" text-anchor="middle">Endpoint</text><text class="s d" x="390" y="360" text-anchor="middle">NIC</text><line class="ln" x1="530" y1="272" x2="530" y2="320"/><rect class="dl" x="470" y="320" width="120" height="52" rx="6" /><text class="h" x="530" y="343" text-anchor="middle">Endpoint</text><text class="s d" x="530" y="360" text-anchor="middle">GPU</text><line class="ln" x1="670" y1="272" x2="670" y2="320"/><rect class="dl" x="610" y="320" width="120" height="52" rx="6" /><text class="h" x="670" y="343" text-anchor="middle">Endpoint</text><text class="s d" x="670" y="360" text-anchor="middle">NVMe SSD</text><text class="xs d" x="560" y="264" text-anchor="middle">downstream ports</text><text class="s d" x="20" y="26" text-anchor="start">Every link is point-to-point.</text><text class="s d" x="20" y="42" text-anchor="start">xN = lanes in that link.</text><text class="s d" x="20" y="392" text-anchor="start">A strict tree: every endpoint has exactly one path back to the Root Complex.</text></svg>`};
DIAGRAMS.lane={title:'Lanes and links',cap:'Each lane carries one transmit pair and one receive pair, so both directions run at full speed at the same time. Link width is the number of lanes bonded together.',svg:`<svg viewBox="0 0 760 296" role="img" aria-label="Lane and link wiring for an x4 link"><title>Lane and link wiring for an x4 link</title><rect class="box" x="20" y="20" width="150" height="210" rx="6" /><text class="h" x="95" y="46" text-anchor="middle">Device A</text><text class="s d" x="95" y="64" text-anchor="middle">e.g. Root Port</text><rect class="box" x="590" y="20" width="150" height="210" rx="6" /><text class="h" x="665" y="46" text-anchor="middle">Device B</text><text class="s d" x="665" y="64" text-anchor="middle">e.g. NVMe SSD</text><text class="xs d" x="380" y="87" text-anchor="middle">Lane 0</text><line class="lna" x1="170" y1="92" x2="582.0" y2="92.0"/><polygon class="ah" points="590.0,92.0 581.0,96.5 581.0,87.5"/><line class="lnc" x1="590" y1="104" x2="178.0" y2="104.0"/><polygon class="ahc" points="170.0,104.0 179.0,99.5 179.0,108.5"/><text class="xs d" x="380" y="121" text-anchor="middle">Lane 1</text><line class="lna" x1="170" y1="126" x2="582.0" y2="126.0"/><polygon class="ah" points="590.0,126.0 581.0,130.5 581.0,121.5"/><line class="lnc" x1="590" y1="138" x2="178.0" y2="138.0"/><polygon class="ahc" points="170.0,138.0 179.0,133.5 179.0,142.5"/><text class="xs d" x="380" y="155" text-anchor="middle">Lane 2</text><line class="lna" x1="170" y1="160" x2="582.0" y2="160.0"/><polygon class="ah" points="590.0,160.0 581.0,164.5 581.0,155.5"/><line class="lnc" x1="590" y1="172" x2="178.0" y2="172.0"/><polygon class="ahc" points="170.0,172.0 179.0,167.5 179.0,176.5"/><text class="xs d" x="380" y="189" text-anchor="middle">Lane 3</text><line class="lna" x1="170" y1="194" x2="582.0" y2="194.0"/><polygon class="ah" points="590.0,194.0 581.0,198.5 581.0,189.5"/><line class="lnc" x1="590" y1="206" x2="178.0" y2="206.0"/><polygon class="ahc" points="170.0,206.0 179.0,201.5 179.0,210.5"/><line class="lna" x1="20" y1="252" x2="46" y2="252"/><text class="s" x="54" y="256" text-anchor="start">TX pair of A = RX pair of B</text><line class="lnc" x1="20" y1="274" x2="46" y2="274"/><text class="s" x="54" y="278" text-anchor="start">TX pair of B = RX pair of A</text><text class="s d" x="740" y="256" text-anchor="end">One lane = 2 differential pairs = 4 wires</text><text class="s d" x="740" y="278" text-anchor="end">An x4 link = 4 lanes = 16 signal wires</text></svg>`};
DIAGRAMS.gens={title:'Generations at a glance',cap:'The per-lane rate doubles every generation. GB/s figures include encoding overhead but not protocol overhead.',svg:`<svg viewBox="0 0 760 342" role="img" aria-label="PCIe generations, encodings and bandwidth"><title>PCIe generations, encodings and bandwidth</title><text class="xs f" x="20" y="22" text-anchor="start">GEN</text><text class="xs f" x="70" y="22" text-anchor="start">PER-LANE RATE</text><text class="xs f" x="340" y="22" text-anchor="start">GT/S</text><text class="xs f" x="410" y="22" text-anchor="start">ENCODING</text><text class="xs f" x="555" y="22" text-anchor="start">x4 GB/S</text><text class="xs f" x="650" y="22" text-anchor="start">x16 GB/S</text><text class="h" x="20" y="58" text-anchor="start">Gen1</text><rect class="tl" x="70" y="43" width="9.765625" height="22" rx="3" /><text class="" x="340" y="59" text-anchor="start">2.5</text><text class="d" x="410" y="59" text-anchor="start">8b/10b</text><text class="ac h" x="555" y="59" text-anchor="start">1.0</text><text class="ac h" x="650" y="59" text-anchor="start">4.0</text><text class="h" x="20" y="102" text-anchor="start">Gen2</text><rect class="tl" x="70" y="87" width="19.53125" height="22" rx="3" /><text class="" x="340" y="103" text-anchor="start">5</text><text class="d" x="410" y="103" text-anchor="start">8b/10b</text><text class="ac h" x="555" y="103" text-anchor="start">2.0</text><text class="ac h" x="650" y="103" text-anchor="start">8.0</text><text class="h" x="20" y="146" text-anchor="start">Gen3</text><rect class="tl" x="70" y="131" width="31.25" height="22" rx="3" /><text class="" x="340" y="147" text-anchor="start">8</text><text class="d" x="410" y="147" text-anchor="start">128b/130b</text><text class="ac h" x="555" y="147" text-anchor="start">3.94</text><text class="ac h" x="650" y="147" text-anchor="start">15.75</text><text class="h" x="20" y="190" text-anchor="start">Gen4</text><rect class="tl" x="70" y="175" width="62.5" height="22" rx="3" /><text class="" x="340" y="191" text-anchor="start">16</text><text class="d" x="410" y="191" text-anchor="start">128b/130b</text><text class="ac h" x="555" y="191" text-anchor="start">7.88</text><text class="ac h" x="650" y="191" text-anchor="start">31.5</text><text class="h" x="20" y="234" text-anchor="start">Gen5</text><rect class="tl" x="70" y="219" width="125.0" height="22" rx="3" /><text class="" x="340" y="235" text-anchor="start">32</text><text class="d" x="410" y="235" text-anchor="start">128b/130b</text><text class="ac h" x="555" y="235" text-anchor="start">15.75</text><text class="ac h" x="650" y="235" text-anchor="start">63.0</text><text class="h" x="20" y="278" text-anchor="start">Gen6</text><rect class="pl" x="70" y="263" width="250.0" height="22" rx="3" /><text class="" x="340" y="279" text-anchor="start">64</text><text class="d" x="410" y="279" text-anchor="start">PAM4 + FLIT</text><text class="ac h" x="555" y="279" text-anchor="start">~32*</text><text class="ac h" x="650" y="279" text-anchor="start">~128*</text><text class="xs d" x="20" y="320" text-anchor="start">* Gen6 is shown raw: FLIT framing and FEC take a few percent of the raw rate.</text><text class="xs d" x="20" y="334" text-anchor="start">All figures are per direction and before TLP/DLLP protocol overhead.</text></svg>`};
DIAGRAMS.stack={title:'Three layers, two devices',cap:'Amber arrows go down on the sender, cyan arrows go up on the receiver. Dashed lines are logical conversations between peer layers; only the Physical Layer touches the wire.',svg:`<svg viewBox="0 0 760 372" role="img" aria-label="Layer stack of two PCIe devices"><title>Layer stack of two PCIe devices</title><rect class="box" x="30" y="16" width="220" height="44" rx="6" /><text class="s" x="140" y="43" text-anchor="middle">Device core / NVMe controller</text><rect class="tl" x="30" y="88" width="220" height="64" rx="6" /><text class="h" x="140" y="113" text-anchor="middle">Transaction Layer</text><text class="s d" x="140" y="133" text-anchor="middle">TLPs · flow control · ordering</text><rect class="dl" x="30" y="172" width="220" height="64" rx="6" /><text class="h" x="140" y="197" text-anchor="middle">Data Link Layer</text><text class="s d" x="140" y="217" text-anchor="middle">seq# · LCRC · ACK/NAK · replay</text><rect class="pl" x="30" y="256" width="220" height="64" rx="6" /><text class="h" x="140" y="281" text-anchor="middle">Physical Layer</text><text class="s d" x="140" y="301" text-anchor="middle">framing · SerDes · LTSSM</text><line class="lna" x1="80" y1="60" x2="80.0" y2="80.0"/><polygon class="ah" points="80.0,88.0 75.5,79.0 84.5,79.0"/><line class="lnc" x1="200" y1="88" x2="200.0" y2="68.0"/><polygon class="ahc" points="200.0,60.0 204.5,69.0 195.5,69.0"/><line class="lna" x1="80" y1="152" x2="80.0" y2="164.0"/><polygon class="ah" points="80.0,172.0 75.5,163.0 84.5,163.0"/><line class="lnc" x1="200" y1="172" x2="200.0" y2="160.0"/><polygon class="ahc" points="200.0,152.0 204.5,161.0 195.5,161.0"/><line class="lna" x1="80" y1="236" x2="80.0" y2="248.0"/><polygon class="ah" points="80.0,256.0 75.5,247.0 84.5,247.0"/><line class="lnc" x1="200" y1="256" x2="200.0" y2="244.0"/><polygon class="ahc" points="200.0,236.0 204.5,245.0 195.5,245.0"/><rect class="box" x="510" y="16" width="220" height="44" rx="6" /><text class="s" x="620" y="43" text-anchor="middle">Device core / NVMe controller</text><rect class="tl" x="510" y="88" width="220" height="64" rx="6" /><text class="h" x="620" y="113" text-anchor="middle">Transaction Layer</text><text class="s d" x="620" y="133" text-anchor="middle">TLPs · flow control · ordering</text><rect class="dl" x="510" y="172" width="220" height="64" rx="6" /><text class="h" x="620" y="197" text-anchor="middle">Data Link Layer</text><text class="s d" x="620" y="217" text-anchor="middle">seq# · LCRC · ACK/NAK · replay</text><rect class="pl" x="510" y="256" width="220" height="64" rx="6" /><text class="h" x="620" y="281" text-anchor="middle">Physical Layer</text><text class="s d" x="620" y="301" text-anchor="middle">framing · SerDes · LTSSM</text><line class="lna" x1="560" y1="60" x2="560.0" y2="80.0"/><polygon class="ah" points="560.0,88.0 555.5,79.0 564.5,79.0"/><line class="lnc" x1="680" y1="88" x2="680.0" y2="68.0"/><polygon class="ahc" points="680.0,60.0 684.5,69.0 675.5,69.0"/><line class="lna" x1="560" y1="152" x2="560.0" y2="164.0"/><polygon class="ah" points="560.0,172.0 555.5,163.0 564.5,163.0"/><line class="lnc" x1="680" y1="172" x2="680.0" y2="160.0"/><polygon class="ahc" points="680.0,152.0 684.5,161.0 675.5,161.0"/><line class="lna" x1="560" y1="236" x2="560.0" y2="248.0"/><polygon class="ah" points="560.0,256.0 555.5,247.0 564.5,247.0"/><line class="lnc" x1="680" y1="256" x2="680.0" y2="244.0"/><polygon class="ahc" points="680.0,236.0 684.5,245.0 675.5,245.0"/><text class="s ac" x="380" y="112" text-anchor="middle">TLP: end-to-end meaning</text><line class="lnd" x1="250" y1="120" x2="510" y2="120"/><text class="s cy" x="380" y="196" text-anchor="middle">DLLP, seq#, LCRC: one hop only</text><line class="lnd" x1="250" y1="204" x2="510" y2="204"/><text class="s gr" x="380" y="262" text-anchor="middle">serial lanes: symbols, ordered sets</text><line class="lna" x1="250" y1="276" x2="502.0" y2="276.0"/><polygon class="ah" points="510.0,276.0 501.0,280.5 501.0,271.5"/><line class="lnc" x1="510" y1="294" x2="258.0" y2="294.0"/><polygon class="ahc" points="250.0,294.0 259.0,289.5 259.0,298.5"/><text class="s d" x="380" y="352" text-anchor="middle">Send: down the stack. Receive: up the stack. Each layer talks to its peer through the layers below it.</text></svg>`};
DIAGRAMS.encap={title:'A TLP on the wire',cap:'Who adds what: the Transaction Layer builds the TLP, the Data Link Layer wraps it with a sequence number and LCRC, and the Physical Layer frames it.',svg:`<svg viewBox="0 0 760 296" role="img" aria-label="TLP encapsulation across the three layers"><title>TLP encapsulation across the three layers</title><rect class="pl" x="50" y="40" width="62" height="60" rx="3" /><text class="s h" x="81.0" y="66" text-anchor="middle">STP</text><text class="xs d" x="81.0" y="84" text-anchor="middle">framing</text><rect class="dl" x="112" y="40" width="62" height="60" rx="3" /><text class="s h" x="143.0" y="66" text-anchor="middle">Seq#</text><text class="xs d" x="143.0" y="84" text-anchor="middle">2 B</text><rect class="tl" x="174" y="40" width="120" height="60" rx="3" /><text class="s h" x="234.0" y="66" text-anchor="middle">Header</text><text class="xs d" x="234.0" y="84" text-anchor="middle">12 or 16 B</text><rect class="tl" x="294" y="40" width="190" height="60" rx="3" /><text class="s h" x="389.0" y="66" text-anchor="middle">Data payload</text><text class="xs d" x="389.0" y="84" text-anchor="middle">0 to 4096 B</text><rect class="tl" x="484" y="40" width="62" height="60" rx="3" /><text class="s h" x="515.0" y="66" text-anchor="middle">ECRC</text><text class="xs d" x="515.0" y="84" text-anchor="middle">4 B, opt.</text><rect class="dl" x="546" y="40" width="66" height="60" rx="3" /><text class="s h" x="579.0" y="66" text-anchor="middle">LCRC</text><text class="xs d" x="579.0" y="84" text-anchor="middle">4 B</text><rect class="pl" x="612" y="40" width="58" height="60" rx="3" /><text class="s h" x="641.0" y="66" text-anchor="middle">END</text><text class="xs d" x="641.0" y="84" text-anchor="middle">framing</text><line class="ln" x1="174" y1="122" x2="546" y2="122"/><line class="ln" x1="174" y1="116" x2="174" y2="122"/><line class="ln" x1="546" y1="116" x2="546" y2="122"/><text class="s ac" x="360.0" y="142" text-anchor="middle">Transaction Layer: the TLP (header, payload, optional ECRC), not modified hop by hop</text><line class="ln" x1="112" y1="170" x2="612" y2="170"/><line class="ln" x1="112" y1="164" x2="112" y2="170"/><line class="ln" x1="612" y1="164" x2="612" y2="170"/><text class="s cy" x="362.0" y="190" text-anchor="middle">Data Link Layer: adds Seq# and LCRC, regenerated on every hop</text><line class="ln" x1="50" y1="218" x2="670" y2="218"/><line class="ln" x1="50" y1="212" x2="50" y2="218"/><line class="ln" x1="670" y1="212" x2="670" y2="218"/><text class="s gr" x="360.0" y="238" text-anchor="middle">Physical Layer: framing (STP/END; 128b/130b uses length tokens) plus encoding and scrambling</text><text class="s d" x="50" y="282" text-anchor="start">ECRC is optional and end-to-end. LCRC is mandatory and per link.</text></svg>`};
DIAGRAMS.pam4={title:'NRZ versus PAM4',cap:'Same symbol rate as Gen5, twice the bits per symbol, but each eye is a third as tall. That lost margin is why Gen6 makes FEC mandatory.',svg:`<svg viewBox="0 0 760 284" role="img" aria-label="NRZ and PAM4 eye diagrams compared"><title>NRZ and PAM4 eye diagrams compared</title><text class="s h" x="190" y="26" text-anchor="middle">NRZ (Gen1-5): 2 levels, 1 bit per symbol</text><text class="s h" x="570" y="26" text-anchor="middle">PAM4 (Gen6): 4 levels, 2 bits per symbol</text><line class="lnd" x1="380" y1="40" x2="380" y2="280"/><line class="lnd" x1="60" y1="70" x2="320" y2="70"/><text class="s d" x="46" y="74" text-anchor="end">1</text><line class="lnd" x1="60" y1="230" x2="320" y2="230"/><text class="s d" x="46" y="234" text-anchor="end">0</text><polygon class="pl" points="100,150 130,74 250,74 280,150 250,226 130,226"/><text class="s" x="190" y="146" text-anchor="middle">one wide eye</text><text class="s d" x="190" y="163" text-anchor="middle">full swing</text><text class="s gr" x="190" y="262" text-anchor="middle">eye height = 1 x swing</text><line class="lnd" x1="440" y1="70" x2="700" y2="70"/><text class="s d" x="426" y="74" text-anchor="end">11</text><line class="lnd" x1="440" y1="123" x2="700" y2="123"/><text class="s d" x="426" y="127" text-anchor="end">10</text><line class="lnd" x1="440" y1="177" x2="700" y2="177"/><text class="s d" x="426" y="181" text-anchor="end">01</text><line class="lnd" x1="440" y1="230" x2="700" y2="230"/><text class="s d" x="426" y="234" text-anchor="end">00</text><polygon class="er" points="500,96.5 530,74.5 610,74.5 640,96.5 610,118.5 530,118.5"/><polygon class="er" points="500,150 530,128 610,128 640,150 610,172 530,172"/><polygon class="er" points="500,203.5 530,181.5 610,181.5 640,203.5 610,225.5 530,225.5"/><text class="s rd" x="570" y="262" text-anchor="middle">three eyes, each 1/3 of the swing = about -9.5 dB SNR</text></svg>`};
DIAGRAMS.ltssm={title:'LTSSM overview',cap:'The link comes up Detect, Polling, Configuration, L0. Recovery is the hub for retraining, and low-power states leave through it (L1) or directly (L0s).',svg:`<svg viewBox="0 0 880 446" role="img" aria-label="LTSSM state diagram"><title>LTSSM state diagram</title><rect class="dl" x="20" y="40" width="110" height="50" rx="6" /><text class="h" x="75" y="70" text-anchor="middle">Detect</text><rect class="dl" x="190" y="40" width="110" height="50" rx="6" /><text class="h" x="245" y="70" text-anchor="middle">Polling</text><rect class="dl" x="360" y="40" width="130" height="50" rx="6" /><text class="h" x="425" y="70" text-anchor="middle">Configuration</text><rect class="tl" x="550" y="40" width="110" height="50" rx="6" /><text class="h lg" x="605" y="70" text-anchor="middle">L0</text><rect class="pl" x="760" y="40" width="100" height="50" rx="6" /><text class="h" x="810" y="70" text-anchor="middle">L0s</text><rect class="er" x="550" y="200" width="110" height="50" rx="6" /><text class="h" x="605" y="230" text-anchor="middle">Recovery</text><rect class="pl" x="760" y="200" width="100" height="50" rx="6" /><text class="h" x="810" y="230" text-anchor="middle">L1</text><rect class="box" x="20" y="360" width="110" height="50" rx="6" /><text class="h" x="75" y="390" text-anchor="middle">Disabled</text><rect class="box" x="190" y="360" width="110" height="50" rx="6" /><text class="h" x="245" y="390" text-anchor="middle">Loopback</text><rect class="box" x="360" y="360" width="130" height="50" rx="6" /><text class="h" x="425" y="390" text-anchor="middle">Hot Reset</text><rect class="pl" x="760" y="360" width="100" height="50" rx="6" /><text class="h" x="810" y="390" text-anchor="middle">L2</text><text class="xs d" x="75" y="30" text-anchor="middle">receiver detect</text><text class="xs d" x="245" y="30" text-anchor="middle">bit/symbol lock, TS1/TS2</text><text class="xs d" x="425" y="30" text-anchor="middle">link #, lane #, width</text><text class="xs d" x="605" y="30" text-anchor="middle">normal operation</text><text class="xs d" x="810" y="30" text-anchor="middle">quick idle</text><line class="lna" x1="130" y1="65" x2="182.0" y2="65.0"/><polygon class="ah" points="190.0,65.0 181.0,69.5 181.0,60.5"/><line class="lna" x1="300" y1="65" x2="352.0" y2="65.0"/><polygon class="ah" points="360.0,65.0 351.0,69.5 351.0,60.5"/><line class="lna" x1="490" y1="65" x2="542.0" y2="65.0"/><polygon class="ah" points="550.0,65.0 541.0,69.5 541.0,60.5"/><line class="lna" x1="660" y1="55" x2="752.0" y2="55.0"/><polygon class="ah" points="760.0,55.0 751.0,59.5 751.0,50.5"/><line class="lna" x1="760" y1="76" x2="668.0" y2="76.0"/><polygon class="ah" points="660.0,76.0 669.0,71.5 669.0,80.5"/><line class="lna" x1="580" y1="90" x2="580.0" y2="192.0"/><polygon class="ah" points="580.0,200.0 575.5,191.0 584.5,191.0"/><line class="lna" x1="630" y1="200" x2="630.0" y2="98.0"/><polygon class="ah" points="630.0,90.0 634.5,99.0 625.5,99.0"/><text class="xs d" x="570" y="150" text-anchor="end">errors, speed or</text><text class="xs d" x="570" y="163" text-anchor="end">width change, L1 exit</text><polyline class="lnd" points="550,225 425,225 425.0,98.0"/><polygon class="ahd" points="425.0,90.0 429.5,99.0 420.5,99.0"/><text class="xs d" x="432" y="200" text-anchor="start">width change</text><polyline class="lnd" points="580,250 580,320 75,320 75.0,98.0"/><polygon class="ahd" points="75.0,90.0 79.5,99.0 70.5,99.0"/><line class="lnd" x1="75" y1="320" x2="75.0" y2="352.0"/><polygon class="ahd" points="75.0,360.0 70.5,351.0 79.5,351.0"/><line class="lnd" x1="245" y1="320" x2="245.0" y2="352.0"/><polygon class="ahd" points="245.0,360.0 240.5,351.0 249.5,351.0"/><line class="lnd" x1="425" y1="320" x2="425.0" y2="352.0"/><polygon class="ahd" points="425.0,360.0 420.5,351.0 429.5,351.0"/><text class="xs d" x="100" y="312" text-anchor="start">timeout: back to Detect.  Or directed: Disabled, Loopback, Hot Reset</text><polyline class="lng" points="660,88 710,88 710,385 752.0,385.0"/><polygon class="ah" points="760.0,385.0 751.0,389.5 751.0,380.5"/><line class="lng" x1="710" y1="225" x2="752.0" y2="225.0"/><polygon class="ah" points="760.0,225.0 751.0,229.5 751.0,220.5"/><line class="lnc" x1="760" y1="208" x2="668.0" y2="208.0"/><polygon class="ahc" points="660.0,208.0 669.0,203.5 669.0,212.5"/><text class="xs d" x="810" y="428" text-anchor="middle">aux power, beacon/WAKE#</text><text class="xs d" x="20" y="436" text-anchor="start">amber = normal path  |  dashed = fallback or directed  |  green = low-power entry from L0  |  cyan = L1 exit via Recovery</text></svg>`};
DIAGRAMS.recovery={title:'Inside Recovery',cap:'Recovery is a small state machine of its own. Speed changes go RcvrCfg to Speed and back to RcvrLock at the new rate; equalization (Gen3+) branches off RcvrLock.',svg:`<svg viewBox="0 0 830 342" role="img" aria-label="LTSSM Recovery sub-states"><title>LTSSM Recovery sub-states</title><rect class="tl" x="20" y="132" width="90" height="46" rx="6" /><text class="h lg" x="65" y="160" text-anchor="middle">L0</text><rect class="grp" x="150" y="60" width="520" height="250" rx="6" /><text class="s h ac" x="162" y="82" text-anchor="start">Recovery</text><rect class="er" x="170" y="130" width="130" height="50" rx="6" /><text class="h" x="235" y="160" text-anchor="middle">RcvrLock</text><rect class="er" x="350" y="130" width="130" height="50" rx="6" /><text class="h" x="415" y="160" text-anchor="middle">RcvrCfg</text><rect class="er" x="530" y="130" width="120" height="50" rx="6" /><text class="h" x="590" y="160" text-anchor="middle">Idle</text><rect class="box" x="170" y="230" width="130" height="50" rx="6" /><text class="h" x="235" y="260" text-anchor="middle">Equalization</text><rect class="box" x="350" y="230" width="130" height="50" rx="6" /><text class="h" x="415" y="260" text-anchor="middle">Speed</text><line class="lna" x1="110" y1="155" x2="162.0" y2="155.0"/><polygon class="ah" points="170.0,155.0 161.0,159.5 161.0,150.5"/><line class="lna" x1="300" y1="155" x2="342.0" y2="155.0"/><polygon class="ah" points="350.0,155.0 341.0,159.5 341.0,150.5"/><line class="lna" x1="480" y1="155" x2="522.0" y2="155.0"/><polygon class="ah" points="530.0,155.0 521.0,159.5 521.0,150.5"/><polyline class="lna" points="590,130 590,100 65,100 65.0,124.0"/><polygon class="ah" points="65.0,132.0 60.5,123.0 69.5,123.0"/><text class="xs d" x="330" y="94" text-anchor="middle">both sides see idle: back to L0</text><line class="lna" x1="215" y1="180" x2="215.0" y2="222.0"/><polygon class="ah" points="215.0,230.0 210.5,221.0 219.5,221.0"/><line class="lnc" x1="255" y1="230" x2="255.0" y2="188.0"/><polygon class="ahc" points="255.0,180.0 259.5,189.0 250.5,189.0"/><text class="xs d" x="268" y="210" text-anchor="start">EQ needed</text><line class="lna" x1="400" y1="180" x2="400.0" y2="222.0"/><polygon class="ah" points="400.0,230.0 395.5,221.0 404.5,221.0"/><text class="xs d" x="410" y="210" text-anchor="start">speed change</text><polyline class="lnc" points="350,250 325,250 325,168 308.0,168.0"/><polygon class="ahc" points="300.0,168.0 309.0,163.5 309.0,172.5"/><rect class="dl" x="715" y="108" width="100" height="44" rx="6" /><text class="s h" x="765" y="135" text-anchor="middle">Configuration</text><line class="lnd" x1="670" y1="130" x2="707.0" y2="130.0"/><polygon class="ahd" points="715.0,130.0 706.0,134.5 706.0,125.5"/><text class="xs d" x="765" y="168" text-anchor="middle">lane / width change</text><rect class="dl" x="715" y="200" width="100" height="44" rx="6" /><text class="s h" x="765" y="227" text-anchor="middle">Detect</text><line class="lnd" x1="670" y1="222" x2="707.0" y2="222.0"/><polygon class="ahd" points="715.0,222.0 706.0,226.5 706.0,217.5"/><text class="xs d" x="765" y="260" text-anchor="middle">timeout, lost link</text><text class="xs d" x="20" y="328" text-anchor="start">RcvrLock: bit/symbol lock and TS1 exchange.  RcvrCfg: TS2 exchange, agree speed and lane config.  Idle: idle data, then L0.</text></svg>`};
DIAGRAMS.eq={title:'The equalization chain',cap:'Three tools fight one problem. TX equalization and the CTLE reshape the frequency response; the DFE cleans up inter-symbol interference after the slicer decision.',svg:`<svg viewBox="0 0 760 304" role="img" aria-label="TX and RX equalization chain with frequency responses"><title>TX and RX equalization chain with frequency responses</title><rect class="tl" x="20" y="30" width="130" height="56" rx="6" /><text class="h" x="85.0" y="55" text-anchor="middle">TX FIR</text><text class="xs d" x="85.0" y="73" text-anchor="middle">pre · main · post</text><rect class="box" x="185" y="30" width="130" height="56" rx="6" /><text class="h" x="250.0" y="55" text-anchor="middle">Channel</text><text class="xs d" x="250.0" y="73" text-anchor="middle">loss · reflections</text><rect class="pl" x="350" y="30" width="120" height="56" rx="6" /><text class="h" x="410.0" y="55" text-anchor="middle">RX CTLE</text><text class="xs d" x="410.0" y="73" text-anchor="middle">analog boost</text><rect class="pl" x="505" y="30" width="110" height="56" rx="6" /><text class="h" x="560.0" y="55" text-anchor="middle">RX DFE</text><text class="xs d" x="560.0" y="73" text-anchor="middle">removes ISI</text><rect class="dl" x="650" y="30" width="100" height="56" rx="6" /><text class="h" x="700.0" y="55" text-anchor="middle">CDR + slicer</text><text class="xs d" x="700.0" y="73" text-anchor="middle">clock + decision</text><line class="lna" x1="150" y1="58" x2="177.0" y2="58.0"/><polygon class="ah" points="185.0,58.0 176.0,62.5 176.0,53.5"/><line class="lna" x1="315" y1="58" x2="342.0" y2="58.0"/><polygon class="ah" points="350.0,58.0 341.0,62.5 341.0,53.5"/><line class="lna" x1="470" y1="58" x2="497.0" y2="58.0"/><polygon class="ah" points="505.0,58.0 496.0,62.5 496.0,53.5"/><line class="lna" x1="615" y1="58" x2="642.0" y2="58.0"/><polygon class="ah" points="650.0,58.0 641.0,62.5 641.0,53.5"/><line class="ln" x1="20" y1="200" x2="150" y2="200"/><line class="ln" x1="20" y1="116" x2="20" y2="200"/><path class="lna" d="M28,190 Q90,186 145,130"/><text class="xs f" x="150" y="214" text-anchor="end">freq</text><text class="xs d" x="85.0" y="236" text-anchor="middle">boosts highs</text><line class="ln" x1="185" y1="200" x2="315" y2="200"/><line class="ln" x1="185" y1="116" x2="185" y2="200"/><path class="lnr" d="M193,130 Q250,186 310,196"/><text class="xs f" x="315" y="214" text-anchor="end">freq</text><text class="xs d" x="250.0" y="236" text-anchor="middle">loses highs</text><line class="ln" x1="350" y1="200" x2="470" y2="200"/><line class="ln" x1="350" y1="116" x2="350" y2="200"/><path class="lng" d="M358,190 Q420,186 465,136"/><text class="xs f" x="470" y="214" text-anchor="end">freq</text><text class="xs d" x="410.0" y="236" text-anchor="middle">peaks at highs</text><line class="ln" x1="505" y1="200" x2="745" y2="200"/><line class="ln" x1="505" y1="116" x2="505" y2="200"/><path class="lng" d="M513,160 L740,160"/><text class="xs f" x="745" y="214" text-anchor="end">freq</text><text class="xs d" x="625" y="236" text-anchor="middle">goal: flat up to Nyquist</text><text class="s d" x="20" y="274" text-anchor="start">The channel steals high frequencies. TX FIR and the CTLE give them back,</text><text class="s d" x="20" y="290" text-anchor="start">and the DFE removes the inter-symbol interference that remains.</text></svg>`};
DIAGRAMS.eqphases={title:'Gen3+ link equalization phases',cap:'Each side ends up with a TX setting chosen by its partner, based on what the partner actually sees at its receiver.',svg:`<svg viewBox="0 0 760 400" role="img" aria-label="Four phases of link equalization between downstream and upstream port"><title>Four phases of link equalization between downstream and upstream port</title><text class="s h" x="150" y="20" text-anchor="middle">Downstream Port (DSP)</text><text class="s h" x="610" y="20" text-anchor="middle">Upstream Port (USP)</text><line class="ln" x1="150" y1="34" x2="150" y2="392"/><line class="ln" x1="610" y1="34" x2="610" y2="392"/><rect x="20" y="44" width="720" height="84" style="fill:rgba(255,255,255,.03);stroke:none"/><rect x="20" y="212" width="720" height="84" style="fill:rgba(255,255,255,.03);stroke:none"/><text class="s h ac" x="30" y="66" text-anchor="start">PHASE 0</text><text class="xs d" x="30" y="82" text-anchor="start">at 2.5/5 GT/s</text><line class="lna" x1="150" y1="100" x2="602.0" y2="100.0"/><polygon class="ah" points="610.0,100.0 601.0,104.5 601.0,95.5"/><text class="s" x="380" y="92" text-anchor="middle">EQ TS2: preset for USP TX + Rx hint</text><text class="xs d" x="380" y="120" text-anchor="middle">agreed before the speed change to 8 GT/s or faster</text><text class="s h ac" x="30" y="150" text-anchor="start">PHASE 1</text><text class="xs d" x="30" y="166" text-anchor="start">new data rate</text><line class="lna" x1="150" y1="150" x2="602.0" y2="150.0"/><polygon class="ah" points="610.0,150.0 601.0,154.5 601.0,145.5"/><line class="lnc" x1="610" y1="174" x2="158.0" y2="174.0"/><polygon class="ahc" points="150.0,174.0 159.0,169.5 159.0,178.5"/><text class="s" x="380" y="143" text-anchor="middle">TS1: preset · FS · LF (DSP to USP)</text><text class="s" x="380" y="167" text-anchor="middle">TS1: preset · FS · LF (USP to DSP)</text><text class="xs d" x="380" y="198" text-anchor="middle">bit lock, symbol lock, block alignment: does the link work at all?</text><text class="s h ac" x="30" y="234" text-anchor="start">PHASE 2</text><text class="xs d" x="30" y="250" text-anchor="start">USP tunes DSP</text><line class="lnc" x1="610" y1="246" x2="158.0" y2="246.0"/><polygon class="ahc" points="150.0,246.0 159.0,241.5 159.0,250.5"/><text class="s" x="380" y="238" text-anchor="middle">USP asks: change your TX coefficients</text><text class="xs d" x="380" y="268" text-anchor="middle">USP measures its receiver and iterates until satisfied</text><text class="s h ac" x="30" y="318" text-anchor="start">PHASE 3</text><text class="xs d" x="30" y="334" text-anchor="start">DSP tunes USP</text><line class="lna" x1="150" y1="330" x2="602.0" y2="330.0"/><polygon class="ah" points="610.0,330.0 601.0,334.5 601.0,325.5"/><text class="s" x="380" y="322" text-anchor="middle">DSP asks: change your TX coefficients</text><text class="xs d" x="380" y="352" text-anchor="middle">DSP measures its receiver and iterates until satisfied</text></svg>`};
DIAGRAMS.replay={title:'ACK/NAK and replay',cap:'Cumulative ACKs free the replay buffer. A NAK acknowledges everything up to its sequence number and asks for the rest to be re-sent in order (go-back-N).',svg:`<svg viewBox="0 0 760 384" role="img" aria-label="ACK NAK replay sequence between sender and receiver"><title>ACK NAK replay sequence between sender and receiver</title><text class="s h" x="170" y="20" text-anchor="middle">Sender (TX)</text><text class="s h" x="590" y="20" text-anchor="middle">Receiver (RX)</text><line class="ln" x1="170" y1="32" x2="170" y2="372"/><line class="ln" x1="590" y1="32" x2="590" y2="372"/><line class="lna" x1="170" y1="60" x2="582.0" y2="79.6"/><polygon class="ah" points="590.0,80.0 580.8,84.1 581.2,75.1"/><text class="s" x="380" y="64" text-anchor="middle">TLP #41</text><line class="lna" x1="170" y1="100" x2="582.0" y2="119.6"/><polygon class="ah" points="590.0,120.0 580.8,124.1 581.2,115.1"/><text class="s" x="380" y="104" text-anchor="middle">TLP #42</text><line class="lna" x1="170" y1="140" x2="582.0" y2="159.6"/><polygon class="ah" points="590.0,160.0 580.8,164.1 581.2,155.1"/><text class="s" x="380" y="144" text-anchor="middle">TLP #43</text><line class="lna" x1="170" y1="180" x2="582.0" y2="199.6"/><polygon class="ah" points="590.0,200.0 580.8,204.1 581.2,195.1"/><text class="s" x="380" y="184" text-anchor="middle">TLP #44</text><line class="lnr" x1="566" y1="152" x2="578" y2="164"/><line class="lnr" x1="578" y1="152" x2="566" y2="164"/><line class="lnr" x1="590" y1="216" x2="178.0" y2="235.6"/><polygon class="ahr" points="170.0,236.0 178.8,231.1 179.2,240.1"/><text class="s rd" x="380" y="220" text-anchor="middle">NAK (seq 42)</text><line class="lna" x1="170" y1="268" x2="582.0" y2="287.6"/><polygon class="ah" points="590.0,288.0 580.8,292.1 581.2,283.1"/><text class="s" x="380" y="272" text-anchor="middle">replay #43</text><line class="lna" x1="170" y1="296" x2="582.0" y2="315.6"/><polygon class="ah" points="590.0,316.0 580.8,320.1 581.2,311.1"/><text class="s" x="380" y="300" text-anchor="middle">replay #44</text><line class="lnc" x1="590" y1="334" x2="178.0" y2="353.6"/><polygon class="ahc" points="170.0,354.0 178.8,349.1 179.2,358.1"/><text class="s cy" x="380" y="338" text-anchor="middle">ACK 44</text><text class="xs d" x="6" y="70" text-anchor="start">buffer: 41</text><text class="xs d" x="6" y="110" text-anchor="start">buffer: 41,42</text><text class="xs d" x="6" y="150" text-anchor="start">+43</text><text class="xs d" x="6" y="190" text-anchor="start">+44</text><text class="xs d" x="6" y="236" text-anchor="start">NAK 42: purge to 42</text><text class="xs d" x="6" y="250" text-anchor="start">keep 43,44</text><text class="xs d" x="6" y="354" text-anchor="start">ACK 44: buffer empty</text><text class="xs d" x="602" y="160" text-anchor="start">LCRC bad: drop, NAK</text><text class="xs d" x="602" y="206" text-anchor="start">#44 out of seq: drop</text><text class="xs d" x="602" y="300" text-anchor="start">#43, #44 in order: accept</text></svg>`};
DIAGRAMS.dllp={title:'DLLP format',cap:'A DLLP is six bytes plus framing: one type byte, three payload bytes, and a 16-bit CRC. DLLPs are not sequence-numbered and never leave the link.',svg:`<svg viewBox="0 0 760 236" role="img" aria-label="Data Link Layer Packet format"><title>Data Link Layer Packet format</title><rect class="pl" x="135" y="30" width="70" height="50" rx="3" /><text class="s h" x="170.0" y="53" text-anchor="middle">SDP</text><text class="xs d" x="170.0" y="69" text-anchor="middle">start</text><rect class="dl" x="205" y="30" width="90" height="50" rx="3" /><text class="s h" x="250.0" y="53" text-anchor="middle">Type</text><text class="xs d" x="250.0" y="69" text-anchor="middle">1 B</text><rect class="dl" x="295" y="30" width="150" height="50" rx="3" /><text class="s h" x="370.0" y="53" text-anchor="middle">Payload</text><text class="xs d" x="370.0" y="69" text-anchor="middle">3 B</text><rect class="dl" x="445" y="30" width="110" height="50" rx="3" /><text class="s h" x="500.0" y="53" text-anchor="middle">CRC-16</text><text class="xs d" x="500.0" y="69" text-anchor="middle">2 B</text><rect class="pl" x="555" y="30" width="70" height="50" rx="3" /><text class="s h" x="590.0" y="53" text-anchor="middle">END</text><text class="xs d" x="590.0" y="69" text-anchor="middle">end</text><text class="xs f" x="20" y="118" text-anchor="start">DLLP KIND</text><text class="xs f" x="210" y="118" text-anchor="start">TYPE BYTE</text><text class="xs f" x="400" y="118" text-anchor="start">PAYLOAD (BYTES 1-3)</text><text class="xs" x="20" y="140" text-anchor="start">Ack</text><text class="xs d" x="210" y="140" text-anchor="start">0000 0000</text><text class="xs d" x="400" y="140" text-anchor="start">AckNak_Seq_Num (12 bits)</text><text class="xs" x="20" y="160" text-anchor="start">Nak</text><text class="xs d" x="210" y="160" text-anchor="start">0001 0000</text><text class="xs d" x="400" y="160" text-anchor="start">AckNak_Seq_Num (12 bits)</text><text class="xs" x="20" y="180" text-anchor="start">InitFC1/2, UpdateFC</text><text class="xs d" x="210" y="180" text-anchor="start">kind in high bits, VC in low 3</text><text class="xs d" x="400" y="180" text-anchor="start">HdrFC (8 bits), DataFC (12 bits)</text><text class="xs" x="20" y="200" text-anchor="start">PM_Enter_L1 / L23 / Request_Ack</text><text class="xs d" x="210" y="200" text-anchor="start">0010 0xxx</text><text class="xs d" x="400" y="200" text-anchor="start">no payload</text></svg>`};
DIAGRAMS.tlphdr={title:'Memory request TLP header (4DW)',cap:'DW0 is common to every TLP. In a memory request DW1 identifies the requester and its tag and carries the byte enables, and DW2/DW3 hold the 64-bit address.',svg:`<svg viewBox="0 0 760 304" role="img" aria-label="Bit map of a four-DW memory request TLP header"><title>Bit map of a four-DW memory request TLP header</title><text class="xs f" x="106.0" y="16" text-anchor="middle">31</text><text class="xs f" x="246.0" y="16" text-anchor="middle">24</text><text class="xs f" x="406.0" y="16" text-anchor="middle">16</text><text class="xs f" x="566.0" y="16" text-anchor="middle">8</text><text class="xs f" x="726.0" y="16" text-anchor="middle">0</text><text class="s h" x="84" y="50" text-anchor="end">DW0</text><rect class="tl" x="96" y="26" width="60" height="40" rx="2" /><text class="s h" x="126.0" y="45" text-anchor="middle">Fmt</text><text class="xs d" x="126.0" y="59" text-anchor="middle">[31:29]</text><rect class="tl" x="156" y="26" width="100" height="40" rx="2" /><text class="s h" x="206.0" y="45" text-anchor="middle">Type</text><text class="xs d" x="206.0" y="59" text-anchor="middle">[28:24]</text><rect class="box" x="256" y="26" width="20" height="40" rx="2" /><text class="xs h" x="266.0" y="50" text-anchor="middle">R*</text><rect class="dl" x="276" y="26" width="60" height="40" rx="2" /><text class="s h" x="306.0" y="45" text-anchor="middle">TC</text><text class="xs d" x="306.0" y="59" text-anchor="middle">[22:20]</text><rect class="box" x="336" y="26" width="20" height="40" rx="2" /><text class="xs h" x="346.0" y="50" text-anchor="middle">R*</text><rect class="dl" x="356" y="26" width="20" height="40" rx="2" /><text class="xs h" x="366.0" y="50" text-anchor="middle">At</text><rect class="box" x="376" y="26" width="20" height="40" rx="2" /><text class="xs h" x="386.0" y="50" text-anchor="middle">R*</text><rect class="dl" x="396" y="26" width="20" height="40" rx="2" /><text class="xs h" x="406.0" y="50" text-anchor="middle">TH</text><rect class="dl" x="416" y="26" width="20" height="40" rx="2" /><text class="xs h" x="426.0" y="50" text-anchor="middle">TD</text><rect class="er" x="436" y="26" width="20" height="40" rx="2" /><text class="xs h" x="446.0" y="50" text-anchor="middle">EP</text><rect class="dl" x="456" y="26" width="40" height="40" rx="2" /><text class="s h" x="476.0" y="45" text-anchor="middle">Attr</text><text class="xs d" x="476.0" y="59" text-anchor="middle">[13:12]</text><rect class="dl" x="496" y="26" width="40" height="40" rx="2" /><text class="s h" x="516.0" y="45" text-anchor="middle">AT</text><text class="xs d" x="516.0" y="59" text-anchor="middle">[11:10]</text><rect class="pl" x="536" y="26" width="200" height="40" rx="2" /><text class="s h" x="636.0" y="45" text-anchor="middle">Length (DW)</text><text class="xs d" x="636.0" y="59" text-anchor="middle">[9:0]</text><text class="s h" x="84" y="102" text-anchor="end">DW1</text><rect class="dl" x="96" y="78" width="320" height="40" rx="2" /><text class="s h" x="256.0" y="97" text-anchor="middle">Requester ID</text><text class="xs d" x="256.0" y="111" text-anchor="middle">[31:16]</text><rect class="dl" x="416" y="78" width="160" height="40" rx="2" /><text class="s h" x="496.0" y="97" text-anchor="middle">Tag</text><text class="xs d" x="496.0" y="111" text-anchor="middle">[15:8]</text><rect class="pl" x="576" y="78" width="80" height="40" rx="2" /><text class="s h" x="616.0" y="97" text-anchor="middle">Last BE</text><text class="xs d" x="616.0" y="111" text-anchor="middle">[7:4]</text><rect class="pl" x="656" y="78" width="80" height="40" rx="2" /><text class="s h" x="696.0" y="97" text-anchor="middle">1st BE</text><text class="xs d" x="696.0" y="111" text-anchor="middle">[3:0]</text><text class="s h" x="84" y="154" text-anchor="end">DW2</text><rect class="tl" x="96" y="130" width="640" height="40" rx="2" /><text class="s h" x="416.0" y="149" text-anchor="middle">Address [63:32]  (4DW header only)</text><text class="xs d" x="416.0" y="163" text-anchor="middle">[31:0]</text><text class="s h" x="84" y="206" text-anchor="end">DW3</text><rect class="tl" x="96" y="182" width="600" height="40" rx="2" /><text class="s h" x="396.0" y="201" text-anchor="middle">Address [31:2]</text><text class="xs d" x="396.0" y="215" text-anchor="middle">[31:2]</text><rect class="box" x="696" y="182" width="40" height="40" rx="2" /><text class="s h" x="716.0" y="201" text-anchor="middle">PH</text><text class="xs d" x="716.0" y="215" text-anchor="middle">[1:0]</text><text class="xs d" x="20" y="246" text-anchor="start">Fmt: 000 = 3DW no data, 001 = 4DW no data, 010 = 3DW with data, 011 = 4DW with data.</text><text class="xs d" x="20" y="262" text-anchor="start">Length 0 encodes 1024 DW.  3DW request: address [31:2] is in DW2 and there is no DW3.</text><text class="xs d" x="20" y="278" text-anchor="start">Completions reuse DW1/DW2 for Completer ID, Status, Byte Count and Lower Address.</text><text class="xs d" x="20" y="294" text-anchor="start">* Reserved, or extended-tag / LN bits, depending on the spec revision.  At = Attr[2].  PH = processing hint (TH set).</text></svg>`};
DIAGRAMS.fc={title:'The flow-control credit loop',cap:'The transmitter may send only while its cumulative consumed count stays inside the cumulative limit the receiver granted. Credits come back as buffers drain, via UpdateFC DLLPs.',svg:`<svg viewBox="0 0 760 284" role="img" aria-label="Flow control credit loop between transmitter and receiver"><title>Flow control credit loop between transmitter and receiver</title><rect class="box" x="20" y="20" width="250" height="250" rx="6" /><text class="s h" x="145" y="44" text-anchor="middle">Transmitter</text><text class="xs d" x="145" y="60" text-anchor="middle">Transaction Layer</text><rect class="tl" x="40" y="76" width="210" height="48" rx="6" /><text class="s h" x="145" y="96" text-anchor="middle">CREDITS_CONSUMED</text><text class="xs d" x="145" y="112" text-anchor="middle">total credits used so far</text><rect class="dl" x="40" y="134" width="210" height="48" rx="6" /><text class="s h" x="145" y="154" text-anchor="middle">CREDIT_LIMIT</text><text class="xs d" x="145" y="170" text-anchor="middle">latest total granted</text><rect class="pl" x="40" y="198" width="210" height="56" rx="6" /><text class="s" x="145" y="217" text-anchor="middle">Gate: send only if</text><text class="s h" x="145" y="234" text-anchor="middle">CONSUMED + needed &lt;= LIMIT</text><text class="xs d" x="145" y="248" text-anchor="middle">(modulo arithmetic)</text><rect class="box" x="490" y="20" width="250" height="250" rx="6" /><text class="s h" x="615" y="44" text-anchor="middle">Receiver</text><text class="xs d" x="615" y="60" text-anchor="middle">Transaction Layer buffers</text><rect class="tl" x="510" y="76" width="30" height="40" rx="2" /><rect class="tl" x="544" y="76" width="30" height="40" rx="2" /><rect class="tl" x="578" y="76" width="30" height="40" rx="2" /><rect class="box" x="612" y="76" width="30" height="40" rx="2" /><rect class="box" x="646" y="76" width="30" height="40" rx="2" /><rect class="box" x="680" y="76" width="30" height="40" rx="2" /><text class="xs d" x="615" y="132" text-anchor="middle">buffer slots: used / free</text><rect class="pl" x="510" y="146" width="210" height="48" rx="6" /><text class="s h" x="615" y="166" text-anchor="middle">CREDITS_ALLOCATED</text><text class="xs d" x="615" y="182" text-anchor="middle">initial + slots freed so far</text><rect class="box" x="510" y="208" width="210" height="46" rx="6" /><text class="s h" x="615" y="227" text-anchor="middle">CREDITS_RECEIVED</text><text class="xs d" x="615" y="243" text-anchor="middle">optional overflow check</text><line class="lna" x1="270" y1="100" x2="482.0" y2="100.0"/><polygon class="ah" points="490.0,100.0 481.0,104.5 481.0,95.5"/><text class="s" x="380" y="92" text-anchor="middle">TLP (uses credits)</text><line class="lnc" x1="490" y1="170" x2="278.0" y2="170.0"/><polygon class="ahc" points="270.0,170.0 279.0,165.5 279.0,174.5"/><text class="s cy" x="380" y="162" text-anchor="middle">UpdateFC DLLP</text><text class="xs d" x="380" y="186" text-anchor="middle">P / NP / Cpl, header + data</text><text class="xs d" x="380" y="232" text-anchor="middle">A credit returns when the receiver</text><text class="xs d" x="380" y="246" text-anchor="middle">DRAINS a slot, not when it ACKs.</text></svg>`};
DIAGRAMS.cfgspace={title:'Configuration space map',cap:'One 4 KB space per function: a 64-byte header, a capability list that starts from the pointer at 34h, and extended capabilities from 100h onward. Always walk the lists; offsets differ between devices.',svg:`<svg viewBox="0 0 760 404" role="img" aria-label="Configuration space layout with capability chains"><title>Configuration space layout with capability chains</title><text class="s h" x="110" y="16" text-anchor="middle">4 KB per function</text><rect class="tl" x="30" y="26" width="160" height="56" rx="6" /><text class="h" x="110" y="48" text-anchor="middle">Header</text><text class="s d" x="110" y="64" text-anchor="middle">00h - 3Fh</text><text class="xs d" x="110" y="77" text-anchor="middle">Type 0 or Type 1</text><rect class="dl" x="30" y="88" width="160" height="116" rx="6" /><text class="h" x="110" y="110" text-anchor="middle">Capabilities</text><text class="s d" x="110" y="126" text-anchor="middle">40h - FFh</text><text class="xs d" x="110" y="144" text-anchor="middle">linked list</text><text class="xs d" x="110" y="158" text-anchor="middle">pointer at 34h</text><rect class="pl" x="30" y="210" width="160" height="150" rx="6" /><text class="h" x="110" y="234" text-anchor="middle">Extended capabilities</text><text class="s d" x="110" y="250" text-anchor="middle">100h - FFFh</text><text class="xs d" x="110" y="268" text-anchor="middle">linked list</text><text class="xs d" x="110" y="282" text-anchor="middle">starts at 100h</text><text class="xs d" x="30" y="378" text-anchor="start">Legacy CF8h/CFCh reaches only 00h - FFh.</text><text class="xs d" x="30" y="392" text-anchor="start">ECAM reaches the full 4 KB.</text><text class="s h" x="500" y="16" text-anchor="middle">Capability chain (8-bit ID, 8-bit next)</text><rect class="box" x="230" y="96" width="84" height="42" rx="6" /><text class="s h" x="272" y="114" text-anchor="middle">Cap Ptr</text><text class="xs d" x="272" y="129" text-anchor="middle">at 34h</text><line class="lnc" x1="314" y1="117" x2="332.0" y2="117.0"/><polygon class="ahc" points="340.0,117.0 331.0,121.5 331.0,112.5"/><rect class="dl" x="340" y="96" width="92" height="42" rx="6" /><text class="s h" x="386" y="114" text-anchor="middle">PM</text><text class="xs d" x="386" y="129" text-anchor="middle">ID 01h</text><line class="lnc" x1="432" y1="117" x2="437.0" y2="117.0"/><polygon class="ahc" points="445.0,117.0 436.0,121.5 436.0,112.5"/><rect class="dl" x="445" y="96" width="92" height="42" rx="6" /><text class="s h" x="491" y="114" text-anchor="middle">MSI</text><text class="xs d" x="491" y="129" text-anchor="middle">ID 05h</text><line class="lnc" x1="537" y1="117" x2="542.0" y2="117.0"/><polygon class="ahc" points="550.0,117.0 541.0,121.5 541.0,112.5"/><rect class="dl" x="550" y="96" width="92" height="42" rx="6" /><text class="s h" x="596" y="114" text-anchor="middle">PCI Express</text><text class="xs d" x="596" y="129" text-anchor="middle">ID 10h</text><line class="lnc" x1="642" y1="117" x2="647.0" y2="117.0"/><polygon class="ahc" points="655.0,117.0 646.0,121.5 646.0,112.5"/><rect class="dl" x="655" y="96" width="92" height="42" rx="6" /><text class="s h" x="701" y="114" text-anchor="middle">MSI-X</text><text class="xs d" x="701" y="129" text-anchor="middle">ID 11h</text><text class="xs d" x="500" y="168" text-anchor="middle">ends when Next = 00h</text><text class="s h" x="500" y="218" text-anchor="middle">Extended chain (16-bit ID, 4-bit version, 12-bit next)</text><rect class="box" x="230" y="234" width="84" height="42" rx="6" /><text class="s h" x="272" y="252" text-anchor="middle">at 100h</text><text class="xs d" x="272" y="267" text-anchor="middle">first entry</text><line class="lng" x1="314" y1="255" x2="332.0" y2="255.0"/><polygon class="ah" points="340.0,255.0 331.0,259.5 331.0,250.5"/><rect class="pl" x="340" y="234" width="92" height="42" rx="6" /><text class="s h" x="386" y="260" text-anchor="middle">AER</text><line class="lng" x1="432" y1="255" x2="437.0" y2="255.0"/><polygon class="ah" points="445.0,255.0 436.0,259.5 436.0,250.5"/><rect class="pl" x="445" y="234" width="92" height="42" rx="6" /><text class="s h" x="491" y="260" text-anchor="middle">Serial No.</text><line class="lng" x1="537" y1="255" x2="542.0" y2="255.0"/><polygon class="ah" points="550.0,255.0 541.0,259.5 541.0,250.5"/><rect class="pl" x="550" y="234" width="92" height="42" rx="6" /><text class="s h" x="596" y="260" text-anchor="middle">SR-IOV</text><line class="lng" x1="642" y1="255" x2="647.0" y2="255.0"/><polygon class="ah" points="655.0,255.0 646.0,259.5 646.0,250.5"/><rect class="pl" x="655" y="234" width="92" height="42" rx="6" /><text class="s h" x="701" y="260" text-anchor="middle">ATS</text><text class="xs d" x="500" y="302" text-anchor="middle">order and presence vary by device; walk the list, never assume offsets</text><text class="xs d" x="230" y="336" text-anchor="start">Type 0 BARs: 10h - 24h (six 32-bit, or three 64-bit).</text><text class="xs d" x="230" y="352" text-anchor="start">Type 1 adds bus numbers and bridge windows.</text></svg>`};
DIAGRAMS.msix={title:'MSI-X structures',cap:'The capability points at a vector table and a pending bit array inside BARs. Firing a vector is nothing more than a 4-byte posted memory write to the address in that table entry.',svg:`<svg viewBox="0 0 760 308" role="img" aria-label="MSI-X capability, table, pending bit array and interrupt write"><title>MSI-X capability, table, pending bit array and interrupt write</title><rect class="dl" x="10" y="20" width="190" height="130" rx="6" /><text class="h" x="105" y="42" text-anchor="middle">MSI-X capability</text><text class="xs d" x="105" y="58" text-anchor="middle">(config space)</text><text class="xs" x="20" y="82" text-anchor="start">Message Control:</text><text class="xs d" x="20" y="96" text-anchor="start"> table size, enable, mask</text><text class="xs" x="20" y="114" text-anchor="start">Table Offset + BIR</text><text class="xs" x="20" y="130" text-anchor="start">PBA Offset + BIR</text><line class="lnc" x1="200" y1="70" x2="254.1" y2="63.0"/><polygon class="ahc" points="262.0,62.0 253.6,67.6 252.5,58.7"/><line class="lnc" x1="200" y1="132" x2="257.2" y2="209.6"/><polygon class="ahc" points="262.0,216.0 253.0,211.4 260.3,206.1"/><text class="s h" x="270" y="14" text-anchor="middle">MSI-X Table (in a BAR): 16 bytes per vector</text><text class="xs d" x="304.5" y="30" text-anchor="middle">Addr Lo</text><rect class="tl" x="262" y="36" width="85" height="24" rx="2" /><rect class="dl" x="262" y="64" width="85" height="24" rx="2" /><rect class="tl" x="262" y="92" width="85" height="24" rx="2" /><text class="xs d" x="389.5" y="30" text-anchor="middle">Addr Hi</text><rect class="tl" x="347" y="36" width="85" height="24" rx="2" /><rect class="dl" x="347" y="64" width="85" height="24" rx="2" /><rect class="tl" x="347" y="92" width="85" height="24" rx="2" /><text class="xs d" x="467.0" y="30" text-anchor="middle">Data</text><rect class="tl" x="432" y="36" width="70" height="24" rx="2" /><rect class="dl" x="432" y="64" width="70" height="24" rx="2" /><rect class="tl" x="432" y="92" width="70" height="24" rx="2" /><text class="xs d" x="532.0" y="30" text-anchor="middle">Ctrl</text><rect class="tl" x="502" y="36" width="60" height="24" rx="2" /><rect class="dl" x="502" y="64" width="60" height="24" rx="2" /><rect class="tl" x="502" y="92" width="60" height="24" rx="2" /><text class="xs d" x="262" y="152" text-anchor="start">vector 0, vector 1, ... up to 2048</text><text class="s h" x="270" y="196" text-anchor="middle">Pending Bit Array (PBA): one bit per vector</text><rect class="box" x="262" y="206" width="18" height="24" rx="2" /><rect class="box" x="282" y="206" width="18" height="24" rx="2" /><rect class="box" x="302" y="206" width="18" height="24" rx="2" /><rect class="er" x="322" y="206" width="18" height="24" rx="2" /><rect class="box" x="342" y="206" width="18" height="24" rx="2" /><rect class="box" x="362" y="206" width="18" height="24" rx="2" /><rect class="box" x="382" y="206" width="18" height="24" rx="2" /><rect class="box" x="402" y="206" width="18" height="24" rx="2" /><rect class="box" x="422" y="206" width="18" height="24" rx="2" /><rect class="er" x="442" y="206" width="18" height="24" rx="2" /><rect class="box" x="462" y="206" width="18" height="24" rx="2" /><rect class="box" x="482" y="206" width="18" height="24" rx="2" /><rect class="box" x="502" y="206" width="18" height="24" rx="2" /><rect class="box" x="522" y="206" width="18" height="24" rx="2" /><rect class="box" x="542" y="206" width="18" height="24" rx="2" /><rect class="box" x="562" y="206" width="18" height="24" rx="2" /><text class="xs d" x="262" y="250" text-anchor="start">a bit is set while its vector is masked, and cleared when the message is sent</text><rect class="pl" x="600" y="30" width="150" height="92" rx="6" /><text class="h" x="675" y="54" text-anchor="middle">Interrupt target</text><text class="s d" x="675" y="72" text-anchor="middle">local APIC, or</text><text class="s d" x="675" y="86" text-anchor="middle">interrupt remapping</text><text class="xs d" x="675" y="106" text-anchor="middle">(IOMMU)</text><line class="lna" x1="562" y1="76" x2="592.0" y2="76.0"/><polygon class="ah" points="600.0,76.0 591.0,80.5 591.0,71.5"/><text class="xs ac" x="675" y="144" text-anchor="middle">posted MWr:</text><text class="xs d" x="675" y="158" text-anchor="middle">Addr = entry Addr</text><text class="xs d" x="675" y="172" text-anchor="middle">payload = entry Data</text><text class="xs d" x="10" y="282" text-anchor="start">BIR (BAR indicator) says which BAR holds each structure.  Vector Ctrl bit 0 masks one vector; Function Mask masks all.</text><text class="xs d" x="10" y="298" text-anchor="start">Memory Space Enable and Bus Master Enable must both be on before a message can be sent.</text></svg>`};
DIAGRAMS.pmstates={title:'D-states, L-states and how they map',cap:'The device state and the link state are different families tied by rules. Software moves the D-state; the ports move the L-state, sometimes on their own through ASPM.',svg:`<svg viewBox="0 0 760 342" role="img" aria-label="Mapping of D-states to link L-states"><title>Mapping of D-states to link L-states</title><text class="s h ac" x="140" y="18" text-anchor="middle">D0 (function on)</text><text class="s h ac" x="400" y="18" text-anchor="middle">D3hot</text><text class="s h ac" x="630" y="18" text-anchor="middle">D3cold</text><rect class="grp" x="20" y="28" width="240" height="250" rx="6" /><rect class="grp" x="290" y="28" width="220" height="250" rx="6" /><rect class="grp" x="540" y="28" width="200" height="250" rx="6" /><rect class="tl" x="70" y="48" width="140" height="40" rx="6" /><text class="h" x="140" y="72" text-anchor="middle">L0</text><rect class="dl" x="30" y="130" width="90" height="40" rx="6" /><text class="h" x="75" y="148" text-anchor="middle">L0s</text><text class="xs d" x="75" y="162" text-anchor="middle">ASPM, per dir</text><rect class="dl" x="150" y="130" width="100" height="40" rx="6" /><text class="h" x="200" y="148" text-anchor="middle">L1</text><text class="xs d" x="200" y="162" text-anchor="middle">ASPM</text><rect class="pl" x="150" y="200" width="100" height="62" rx="6" /><text class="h" x="200" y="220" text-anchor="middle">L1.1</text><text class="h" x="200" y="238" text-anchor="middle">L1.2</text><text class="xs d" x="200" y="254" text-anchor="middle">CLKREQ#, LTR</text><line class="lnc" x1="120" y1="88" x2="94.8" y2="121.6"/><polygon class="ahc" points="90.0,128.0 91.8,118.1 99.0,123.5"/><line class="lnc" x1="180" y1="88" x2="196.4" y2="120.8"/><polygon class="ahc" points="200.0,128.0 192.0,122.0 200.0,117.9"/><line class="lng" x1="200" y1="170" x2="200.0" y2="190.0"/><polygon class="ah" points="200.0,198.0 195.5,189.0 204.5,189.0"/><rect class="dl" x="330" y="100" width="140" height="56" rx="6" /><text class="h" x="400" y="124" text-anchor="middle">L1</text><text class="xs d" x="400" y="142" text-anchor="middle">forced by software</text><rect class="box" x="570" y="60" width="140" height="46" rx="6" /><text class="h" x="640" y="80" text-anchor="middle">L2</text><text class="xs d" x="640" y="96" text-anchor="middle">aux power on</text><rect class="box" x="570" y="130" width="140" height="46" rx="6" /><text class="h" x="640" y="150" text-anchor="middle">L3</text><text class="xs d" x="640" y="166" text-anchor="middle">everything off</text><line class="lna" x1="260" y1="128" x2="322.0" y2="128.0"/><polygon class="ah" points="330.0,128.0 321.0,132.5 321.0,123.5"/><text class="xs ac" x="295" y="118" text-anchor="middle">PMCSR</text><text class="xs d" x="295" y="148" text-anchor="middle">PM_Enter_L1</text><line class="lna" x1="470" y1="128" x2="562.3" y2="102.2"/><polygon class="ah" points="570.0,100.0 562.5,106.8 560.1,98.1"/><text class="xs d" x="520" y="152" text-anchor="middle">PME_Turn_Off</text><text class="xs d" x="520" y="166" text-anchor="middle">PM_Enter_L23</text><line class="lnd" x1="640" y1="106" x2="640.0" y2="122.0"/><polygon class="ahd" points="640.0,130.0 635.5,121.0 644.5,121.0"/><text class="xs d" x="20" y="298" text-anchor="start">D-state: software, per function.  L-state: the link, run by both ports (and by ASPM on its own).</text><text class="xs d" x="20" y="314" text-anchor="start">D3hot forces L1.  D3cold means the link is in L2 or L3.</text><text class="xs d" x="20" y="330" text-anchor="start">NVMe PS0..PSn is a third, independent ladder inside the controller.</text></svg>`};
DIAGRAMS.aer={title:'Error classes and reporting path',cap:'Errors are classed, reported to the Root Complex as ERR_* messages, and then handled by firmware, the OS AER driver, or by Downstream Port Containment.',svg:`<svg viewBox="0 0 760 302" role="img" aria-label="PCIe error classification and reporting path"><title>PCIe error classification and reporting path</title><rect class="box" x="10" y="110" width="130" height="60" rx="6" /><text class="h" x="75" y="136" text-anchor="middle">Error detected</text><text class="xs d" x="75" y="154" text-anchor="middle">PHY / DLL / TL</text><line class="lna" x1="140" y1="140" x2="195.6" y2="54.7"/><polygon class="ah" points="200.0,48.0 198.9,58.0 191.3,53.1"/><rect class="pl" x="200" y="20" width="200" height="56" rx="6" /><text class="s h" x="300" y="42" text-anchor="middle">Correctable</text><text class="xs d" x="300" y="57" text-anchor="middle">Bad TLP, Bad DLLP,</text><text class="xs d" x="300" y="69" text-anchor="middle">Replay Timeout, Rx Error</text><line class="lnc" x1="400" y1="48" x2="465.2" y2="133.6"/><polygon class="ahc" points="470.0,140.0 461.0,135.6 468.1,130.1"/><text class="xs cy" x="450" y="66" text-anchor="middle">ERR_COR</text><line class="lna" x1="140" y1="140" x2="192.0" y2="138.3"/><polygon class="ah" points="200.0,138.0 191.2,142.8 190.9,133.8"/><rect class="tl" x="200" y="110" width="200" height="56" rx="6" /><text class="s h" x="300" y="132" text-anchor="middle">Uncorrectable non-fatal</text><text class="xs d" x="300" y="147" text-anchor="middle">UR, CA, Completion Timeout,</text><text class="xs d" x="300" y="159" text-anchor="middle">Poisoned TLP, ECRC</text><line class="lnc" x1="400" y1="138" x2="462.0" y2="139.8"/><polygon class="ahc" points="470.0,140.0 460.9,144.2 461.1,135.2"/><text class="xs cy" x="435" y="124" text-anchor="middle">ERR_NONFATAL</text><line class="lnr" x1="140" y1="140" x2="195.5" y2="221.4"/><polygon class="ahr" points="200.0,228.0 191.2,223.1 198.6,218.0"/><rect class="er" x="200" y="200" width="200" height="56" rx="6" /><text class="s h" x="300" y="222" text-anchor="middle">Uncorrectable fatal</text><text class="xs d" x="300" y="237" text-anchor="middle">Malformed TLP, Surprise Down,</text><text class="xs d" x="300" y="249" text-anchor="middle">DL Protocol Error, FC error</text><line class="lnc" x1="400" y1="228" x2="465.0" y2="146.3"/><polygon class="ahc" points="470.0,140.0 467.9,149.8 460.9,144.2"/><text class="xs cy" x="452" y="214" text-anchor="middle">ERR_FATAL</text><rect class="dl" x="470" y="100" width="120" height="80" rx="6" /><text class="h" x="530" y="126" text-anchor="middle">Root Complex</text><text class="xs d" x="530" y="144" text-anchor="middle">Root Error Status</text><text class="xs d" x="530" y="158" text-anchor="middle">Error Source ID</text><line class="lna" x1="590" y1="140" x2="632.0" y2="140.0"/><polygon class="ah" points="640.0,140.0 631.0,144.5 631.0,135.5"/><rect class="box" x="640" y="60" width="110" height="44" rx="6" /><text class="s h" x="695" y="80" text-anchor="middle">Firmware-first</text><text class="xs d" x="695" y="95" text-anchor="middle">may see it first</text><rect class="box" x="640" y="112" width="110" height="44" rx="6" /><text class="s h" x="695" y="132" text-anchor="middle">OS AER driver</text><text class="xs d" x="695" y="147" text-anchor="middle">log, reset, retry</text><rect class="er" x="640" y="164" width="110" height="44" rx="6" /><text class="s h" x="695" y="184" text-anchor="middle">DPC</text><text class="xs d" x="695" y="199" text-anchor="middle">contain the port</text><text class="xs d" x="20" y="274" text-anchor="start">Severity of each uncorrectable type is programmable (Uncorrectable Error Severity); the placement above is the default.</text><text class="xs d" x="20" y="290" text-anchor="start">Header Log holds the offending TLP header, when the error came with one.</text></svg>`};
DIAGRAMS.sriov={title:'SR-IOV: one PF, many VFs',cap:'A Physical Function creates lightweight Virtual Functions, each with its own routing ID, BAR slice and interrupt vectors. They all share the same link and the same device internals.',svg:`<svg viewBox="0 0 760 384" role="img" aria-label="SR-IOV physical function and virtual functions sharing one link"><title>SR-IOV physical function and virtual functions sharing one link</title><rect class="tl" x="230" y="8" width="300" height="46" rx="6" /><text class="h" x="380" y="28" text-anchor="middle">Host memory + IOMMU</text><text class="xs d" x="380" y="44" text-anchor="middle">translates each requester ID separately</text><rect class="box" x="290" y="76" width="180" height="34" rx="6" /><text class="s h" x="380" y="98" text-anchor="middle">Root Port</text><line class="lnd" x1="380" y1="54" x2="380.0" y2="68.0"/><polygon class="ahd" points="380.0,76.0 375.5,67.0 384.5,67.0"/><line class="lna" x1="380" y1="110" x2="380" y2="150"/><text class="xs d" x="396" y="134" text-anchor="start">one shared link</text><rect class="grp" x="20" y="150" width="720" height="190" rx="6" /><text class="s d" x="36" y="168" text-anchor="start">One SSD, one link, one controller</text><rect class="tl" x="40" y="180" width="150" height="140" rx="6" /><text class="h" x="115" y="202" text-anchor="middle">PF</text><text class="xs" x="115" y="218" text-anchor="middle">RID  b:d.0</text><text class="xs d" x="115" y="234" text-anchor="middle">full config space</text><text class="xs d" x="115" y="248" text-anchor="middle">SR-IOV capability</text><text class="xs d" x="115" y="262" text-anchor="middle">admin, VF setup</text><text class="xs d" x="115" y="300" text-anchor="middle">owns VF enable</text><rect class="dl" x="220" y="180" width="150" height="140" rx="6" /><text class="h" x="295" y="202" text-anchor="middle">VF1</text><text class="xs" x="295" y="218" text-anchor="middle">RID  b:d.1*</text><text class="xs d" x="295" y="234" text-anchor="middle">own BAR slice</text><text class="xs d" x="295" y="248" text-anchor="middle">own MSI-X vectors</text><text class="xs d" x="295" y="262" text-anchor="middle">own queues</text><text class="xs d" x="295" y="300" text-anchor="middle">own FLR</text><rect class="dl" x="390" y="180" width="150" height="140" rx="6" /><text class="h" x="465" y="202" text-anchor="middle">VF2</text><text class="xs" x="465" y="218" text-anchor="middle">RID  b:d.2*</text><text class="xs d" x="465" y="234" text-anchor="middle">own BAR slice</text><text class="xs d" x="465" y="248" text-anchor="middle">own MSI-X vectors</text><text class="xs d" x="465" y="262" text-anchor="middle">own queues</text><text class="xs d" x="465" y="300" text-anchor="middle">own FLR</text><rect class="dl" x="560" y="180" width="150" height="140" rx="6" /><text class="h" x="635" y="202" text-anchor="middle">VF3</text><text class="xs" x="635" y="218" text-anchor="middle">RID  b:d.3*</text><text class="xs d" x="635" y="234" text-anchor="middle">own BAR slice</text><text class="xs d" x="635" y="248" text-anchor="middle">own MSI-X vectors</text><text class="xs d" x="635" y="262" text-anchor="middle">own queues</text><text class="xs d" x="635" y="300" text-anchor="middle">own FLR</text><text class="s d" x="380" y="358" text-anchor="middle">DMA from each VF carries that VF's requester ID, so the IOMMU can give every VM its own mapping.</text><text class="xs d" x="380" y="374" text-anchor="middle">* Routing IDs come from the PF's First VF Offset and VF Stride, and may cross into higher bus numbers.</text></svg>`};
DIAGRAMS.flit={title:'FLIT versus non-FLIT framing',cap:'FLIT mode replaces per-TLP framing, sequence numbers and LCRC with fixed 256-byte flits protected by a flit CRC and a light-weight FEC.',svg:`<svg viewBox="0 0 760 316" role="img" aria-label="Non-FLIT TLP framing compared with a 256 byte flit"><title>Non-FLIT TLP framing compared with a 256 byte flit</title><text class="s h ac" x="20" y="18" text-anchor="start">NON-FLIT: each TLP framed separately</text><rect class="pl" x="20" y="28" width="60" height="40" rx="2" /><text class="s h" x="50.0" y="53" text-anchor="middle">STP</text><rect class="dl" x="80" y="28" width="70" height="40" rx="2" /><text class="s h" x="115.0" y="53" text-anchor="middle">Seq #</text><rect class="tl" x="150" y="28" width="110" height="40" rx="2" /><text class="s h" x="205.0" y="53" text-anchor="middle">Header</text><rect class="tl" x="260" y="28" width="250" height="40" rx="2" /><text class="s h" x="385.0" y="53" text-anchor="middle">Payload</text><rect class="tl" x="510" y="28" width="60" height="40" rx="2" /><text class="s h" x="540.0" y="53" text-anchor="middle">ECRC</text><rect class="dl" x="570" y="28" width="70" height="40" rx="2" /><text class="s h" x="605.0" y="53" text-anchor="middle">LCRC</text><rect class="pl" x="640" y="28" width="60" height="40" rx="2" /><text class="s h" x="670.0" y="53" text-anchor="middle">END</text><text class="xs d" x="20" y="88" text-anchor="start">DLLPs are separate 6-byte packets. Sequence number and LCRC are per TLP.</text><text class="s h ac" x="20" y="126" text-anchor="start">FLIT MODE: fixed 256-byte flit (bar is not to scale)</text><rect class="tl" x="20" y="136" width="460" height="50" rx="2" /><text class="s h" x="250.0" y="166" text-anchor="middle">TLP area  236 B</text><rect class="dl" x="480" y="136" width="80" height="50" rx="2" /><text class="s h" x="520.0" y="166" text-anchor="middle">DLP 6 B</text><rect class="er" x="560" y="136" width="80" height="50" rx="2" /><text class="s h" x="600.0" y="166" text-anchor="middle">CRC 8 B</text><rect class="pl" x="640" y="136" width="80" height="50" rx="2" /><text class="s h" x="680.0" y="166" text-anchor="middle">FEC 6 B</text><line class="lna" x1="20" y1="200" x2="640" y2="200"/><line class="lna" x1="20" y1="196" x2="20" y2="204"/><line class="lna" x1="640" y1="196" x2="640" y2="204"/><text class="xs ac" x="330" y="216" text-anchor="middle">CRC covers TLP area + DLP (bytes 0 - 241)</text><line class="lnc" x1="20" y1="228" x2="720" y2="228"/><line class="lnc" x1="20" y1="224" x2="20" y2="232"/><line class="lnc" x1="720" y1="224" x2="720" y2="232"/><text class="xs cy" x="370" y="244" text-anchor="middle">FEC (three interleaved 2-byte groups) protects everything before it</text><text class="xs d" x="20" y="274" text-anchor="start">Overhead is 20 of 256 bytes: DLP 6 + CRC 8 + FEC 6.</text><text class="xs d" x="20" y="290" text-anchor="start">Acks, Naks and credits ride in the DLP; a bad CRC after FEC triggers a flit replay.</text><text class="xs d" x="20" y="306" text-anchor="start">The 236 / 6 / 8 / 6 split is the commonly published layout; confirm it in the Base Specification before quoting.</text></svg>`};
DIAGRAMS.resets={title:'What each reset clears',cap:'Reset types differ in scope. Only a Fundamental Reset restarts everything, and error status in sticky registers survives most of the others, so read it before you reset.',svg:`<svg viewBox="0 0 760 350" role="img" aria-label="Matrix of reset types against what each resets"><title>Matrix of reset types against what each resets</title><text class="xs f" x="254.0" y="20" text-anchor="middle">Link</text><text class="xs f" x="362.0" y="20" text-anchor="middle">Config regs</text><text class="xs f" x="470.0" y="20" text-anchor="middle">Device logic</text><text class="xs f" x="578.0" y="20" text-anchor="middle">Sticky (AER)</text><text class="xs f" x="686.0" y="20" text-anchor="middle">NVMe controller</text><text class="s h" x="10" y="56" text-anchor="start">PERST# (fundamental)</text><rect class="er" x="202" y="30" width="104" height="38" rx="3" /><text class="xs" x="254.0" y="54" text-anchor="middle">retrains</text><rect class="er" x="310" y="30" width="104" height="38" rx="3" /><text class="xs" x="362.0" y="54" text-anchor="middle">reset</text><rect class="er" x="418" y="30" width="104" height="38" rx="3" /><text class="xs" x="470.0" y="54" text-anchor="middle">reset</text><rect class="er" x="526" y="30" width="104" height="38" rx="3" /><text class="xs" x="578.0" y="54" text-anchor="middle">cleared*</text><rect class="er" x="634" y="30" width="104" height="38" rx="3" /><text class="xs" x="686.0" y="54" text-anchor="middle">reset</text><text class="s h" x="10" y="100" text-anchor="start">Hot reset (secondary bus)</text><rect class="er" x="202" y="74" width="104" height="38" rx="3" /><text class="xs" x="254.0" y="98" text-anchor="middle">retrains</text><rect class="er" x="310" y="74" width="104" height="38" rx="3" /><text class="xs" x="362.0" y="98" text-anchor="middle">reset</text><rect class="er" x="418" y="74" width="104" height="38" rx="3" /><text class="xs" x="470.0" y="98" text-anchor="middle">reset</text><rect class="pl" x="526" y="74" width="104" height="38" rx="3" /><text class="xs" x="578.0" y="98" text-anchor="middle">kept</text><rect class="er" x="634" y="74" width="104" height="38" rx="3" /><text class="xs" x="686.0" y="98" text-anchor="middle">reset</text><text class="s h" x="10" y="144" text-anchor="start">FLR</text><rect class="pl" x="202" y="118" width="104" height="38" rx="3" /><text class="xs" x="254.0" y="142" text-anchor="middle">stays up</text><rect class="er" x="310" y="118" width="104" height="38" rx="3" /><text class="xs" x="362.0" y="142" text-anchor="middle">reset</text><rect class="er" x="418" y="118" width="104" height="38" rx="3" /><text class="xs" x="470.0" y="142" text-anchor="middle">function only</text><rect class="pl" x="526" y="118" width="104" height="38" rx="3" /><text class="xs" x="578.0" y="142" text-anchor="middle">kept</text><rect class="er" x="634" y="118" width="104" height="38" rx="3" /><text class="xs" x="686.0" y="142" text-anchor="middle">reset</text><text class="s h" x="10" y="188" text-anchor="start">D3hot to D0</text><rect class="pl" x="202" y="162" width="104" height="38" rx="3" /><text class="xs" x="254.0" y="186" text-anchor="middle">stays up</text><rect class="tl" x="310" y="162" width="104" height="38" rx="3" /><text class="xs" x="362.0" y="186" text-anchor="middle">if soft reset</text><rect class="tl" x="418" y="162" width="104" height="38" rx="3" /><text class="xs" x="470.0" y="186" text-anchor="middle">if soft reset</text><rect class="pl" x="526" y="162" width="104" height="38" rx="3" /><text class="xs" x="578.0" y="186" text-anchor="middle">kept</text><rect class="tl" x="634" y="162" width="104" height="38" rx="3" /><text class="xs" x="686.0" y="186" text-anchor="middle">varies</text><text class="s h" x="10" y="232" text-anchor="start">NVMe CC.EN 1 to 0</text><rect class="pl" x="202" y="206" width="104" height="38" rx="3" /><text class="xs" x="254.0" y="230" text-anchor="middle">untouched</text><rect class="pl" x="310" y="206" width="104" height="38" rx="3" /><text class="xs" x="362.0" y="230" text-anchor="middle">untouched</text><rect class="tl" x="418" y="206" width="104" height="38" rx="3" /><text class="xs" x="470.0" y="230" text-anchor="middle">controller only</text><rect class="pl" x="526" y="206" width="104" height="38" rx="3" /><text class="xs" x="578.0" y="230" text-anchor="middle">kept</text><rect class="er" x="634" y="206" width="104" height="38" rx="3" /><text class="xs" x="686.0" y="230" text-anchor="middle">reset</text><text class="s h" x="10" y="276" text-anchor="start">NVMe NSSR</text><rect class="tl" x="202" y="250" width="104" height="38" rx="3" /><text class="xs" x="254.0" y="274" text-anchor="middle">varies</text><rect class="tl" x="310" y="250" width="104" height="38" rx="3" /><text class="xs" x="362.0" y="274" text-anchor="middle">varies</text><rect class="er" x="418" y="250" width="104" height="38" rx="3" /><text class="xs" x="470.0" y="274" text-anchor="middle">subsystem</text><rect class="tl" x="526" y="250" width="104" height="38" rx="3" /><text class="xs" x="578.0" y="274" text-anchor="middle">varies</text><rect class="er" x="634" y="250" width="104" height="38" rx="3" /><text class="xs" x="686.0" y="274" text-anchor="middle">reset</text><text class="xs d" x="10" y="306" text-anchor="start">Red = cleared or restarted.  Green = untouched.  Amber = depends on the device or on a config bit.</text><text class="xs d" x="10" y="322" text-anchor="start">* Sticky registers survive a Fundamental Reset only when auxiliary power keeps them alive. Read and log AER before you reset.</text><text class="xs d" x="10" y="338" text-anchor="start">Exact behavior of NSSR, D3hot to D0 and sticky rules is device- and spec-revision dependent: verify for your part.</text></svg>`};
DIAGRAMS.nvmeflow={title:'One 4 KB NVMe read on the bus',cap:'Only the SQE fetch is non-posted. The data, the completion entry and the interrupt are posted writes that arrive in order, which is what lets the host trust the completion.',svg:`<svg viewBox="0 0 760 436" role="img" aria-label="Sequence of PCIe transactions for a 4 KB NVMe read"><title>Sequence of PCIe transactions for a 4 KB NVMe read</title><text class="s h" x="170" y="20" text-anchor="middle">Host CPU + memory</text><text class="s h" x="590" y="20" text-anchor="middle">NVMe SSD</text><line class="ln" x1="170" y1="32" x2="170" y2="424"/><line class="ln" x1="590" y1="32" x2="590" y2="424"/><rect class="box" x="180" y="44" width="200" height="26" rx="6" /><text class="xs d" x="280" y="61" text-anchor="middle">write 64 B SQE into SQ ring (no bus event)</text><text class="s ac" x="6" y="60" text-anchor="start">1</text><line class="lna" x1="170" y1="96" x2="582.0" y2="103.8"/><polygon class="ah" points="590.0,104.0 580.9,108.3 581.1,99.3"/><text class="s" x="380" y="90" text-anchor="middle">MWr 4 B: SQ tail doorbell</text><text class="s ac" x="6" y="100" text-anchor="start">2</text><line class="lnc" x1="590" y1="146" x2="178.0" y2="153.8"/><polygon class="ahc" points="170.0,154.0 178.9,149.3 179.1,158.3"/><text class="s" x="380" y="140" text-anchor="middle">MRd 64 B: fetch SQE</text><text class="xs d" x="380" y="166" text-anchor="middle">non-posted, needs a tag</text><text class="s ac" x="6" y="150" text-anchor="start">3</text><line class="lnc" x1="170" y1="196" x2="582.0" y2="203.8"/><polygon class="ahc" points="590.0,204.0 580.9,208.3 581.1,199.3"/><text class="s" x="380" y="190" text-anchor="middle">CplD 64 B: the SQE</text><text class="s ac" x="6" y="200" text-anchor="start"></text><line class="lna" x1="590" y1="246" x2="178.0" y2="253.8"/><polygon class="ah" points="170.0,254.0 178.9,249.3 179.1,258.3"/><text class="s" x="380" y="240" text-anchor="middle">MWr x N: 4 KB data, each &lt;= MPS</text><text class="xs d" x="380" y="266" text-anchor="middle">after the NAND read</text><text class="s ac" x="6" y="250" text-anchor="start">4</text><line class="lna" x1="590" y1="296" x2="178.0" y2="303.8"/><polygon class="ah" points="170.0,304.0 178.9,299.3 179.1,308.3"/><text class="s" x="380" y="290" text-anchor="middle">MWr 16 B: CQE with phase tag</text><text class="s ac" x="6" y="300" text-anchor="start">5</text><line class="lna" x1="590" y1="340" x2="178.0" y2="347.8"/><polygon class="ah" points="170.0,348.0 178.9,343.3 179.1,352.3"/><text class="s" x="380" y="334" text-anchor="middle">MWr 4 B: MSI-X message</text><text class="s ac" x="6" y="344" text-anchor="start">6</text><line class="lna" x1="170" y1="384" x2="582.0" y2="391.8"/><polygon class="ah" points="590.0,392.0 580.9,396.3 581.1,387.3"/><text class="s" x="380" y="378" text-anchor="middle">MWr 4 B: CQ head doorbell</text><text class="xs d" x="380" y="404" text-anchor="middle">after the host consumed the CQE</text><text class="s ac" x="6" y="388" text-anchor="start">7</text><rect class="er" x="600" y="232" width="150" height="66" rx="3" /><text class="s h" x="675" y="252" text-anchor="middle">posted stream</text><text class="xs d" x="675" y="268" text-anchor="middle">data, CQE, MSI-X</text><text class="xs d" x="675" y="284" text-anchor="middle">stay in order</text></svg>`};
